const menu=document.querySelector('.menu-btn'),nav=document.querySelector('.nav');menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open);menu.textContent=open?'Schließen':'Menü'});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('open')){menu.click();menu.focus()}});
const search=document.querySelector('#blog-search'),cat=document.querySelector('#blog-category'),month=document.querySelector('#blog-month');function filterPosts(){let n=0;document.querySelectorAll('[data-post]').forEach(card=>{const ok=card.dataset.search.includes(search.value.toLocaleLowerCase('de'))&&(!cat.value||card.dataset.category===cat.value)&&(!month.value||card.dataset.month===month.value);card.classList.toggle('hidden',!ok);if(ok)n++});document.querySelector('#post-count').textContent=n+' Beiträge';document.querySelector('.empty').style.display=n?'none':'block'}search?.addEventListener('input',filterPosts);cat?.addEventListener('change',filterPosts);month?.addEventListener('change',filterPosts);
document.querySelector('#contact-form')?.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);const body=`Guten Tag COMPAKT-Team,\n\n${d.get('message')}\n\nGewünschte Leistung: ${d.get('service')}\nObjekt / Standort: ${d.get('location')}\nFirma: ${d.get('company')}\nName: ${d.get('name')}\nE-Mail: ${d.get('email')}\nTelefon: ${d.get('phone')}`;const url='mailto:info@compakt-service.de?subject='+encodeURIComponent('Website-Anfrage: '+d.get('service'))+'&body='+encodeURIComponent(body);window.location.href=url;document.querySelector('#form-status').textContent='Die Anfrage wurde für Ihr E-Mail-Programm vorbereitet. Bitte senden Sie die Nachricht dort ab. Alternativ schreiben Sie direkt an info@compakt-service.de.'});
const requested=new URLSearchParams(location.search).get('leistung');if(requested){const keys=['gebaeudereinigung','wachschutz','winterdienst','grafittientfernung','hausmeister','gruenflaechenpflege','immobilienservice','entlastungsbetrag','drohnenservice'];const index=keys.indexOf(requested);const select=document.querySelector('select[name=service]');if(select&&index>=0)select.selectedIndex=index;}

const topicNames={unterhaltsreinigung:'Unterhaltsreinigung',bueroreinigung:'Büroreinigung',glasreinigung:'Glasreinigung',treppenhausreinigung:'Treppenhausreinigung'};if(topicNames[requested]){const select=document.querySelector('select[name=service]');if(select){select.add(new Option(topicNames[requested],topicNames[requested],true,true));}}
